// find the pipeline channel by name; a 30-minute window (dedupe by ts keeps it idempotent)
const want = 'etsy-shop-alerts';
const chans = ($input.first().json.channels || []);
const ch = chans.find(c => c.name === want);
if (!ch) throw new Error(`channel ${want} not visible to the bot — invite it with /invite`);
return [{ json: { channel: ch.id, oldest: (Date.now() / 1000 - 1800).toFixed(3) } }];

// Read current review threads at any age; acknowledge a verdict only after the sheet write succeeds.
const st = $getWorkflowStaticData('global'); st.seen = st.seen || [];
const top = $('Channel history').first().json.messages || [];
const oldest = Number($('Pick channel').first().json.oldest);
const parents = {}; for (const m of top) parents[m.ts] = m;
for (const m of Object.values(st.review_threads || {})) { parents[m.ts] = m; for (const r of m.replaced || []) parents[r.ts] = r; }
const all = top.filter(m => Number(m.ts) >= oldest).map(m => ({m,parent:null}));
for (const it of $('Thread replies').all()) {
  if (it.json.ok === false) throw new Error('Slack review replies unavailable');
  const arr = it.json.messages || [];
  for (const m of arr) if (m.thread_ts && m.ts !== m.thread_ts) all.push({m,parent:parents[m.thread_ts] || arr.find(x=>x.ts===m.thread_ts)});
}
all.sort((a,b)=>Number(b.m.ts)-Number(a.m.ts));
const out = [], selected = new Set(), timestamps = new Set();
for (const {m,parent} of all) {
  if (m.bot_id || (m.subtype && !['file_share','thread_broadcast'].includes(m.subtype)) || st.seen.includes(m.ts) || timestamps.has(m.ts)) continue;
  timestamps.add(m.ts);
  const text = String(m.text || '').trim();
  const match = text.match(/^(approve|approved|revise|revised|reject|rejected)\b\s*(?:(?:R|r)\s*)?(\d{2,4})?\b[\s:\-–—]*([\s\S]*)$/i);
  if (!match) continue;
  let sku = match[2] ? 'R'+match[2] : '';
  if (!sku && parent) {const p = String(parent.text||'').match(/\b(R\d{2,4})\b/i); if (p) sku=p[1].toUpperCase();}
  if (!/^R8\d{3}$/.test(sku) || selected.has(sku)) continue;
  const current = (st.review_threads||{})[sku];
  // A reply on a post the newest one replaced counts only when it came after the newest post and both show the same
  // Drive preview (Collect threads keeps only those): the link opens the newest version (R404, 2026-09-15).
  const onReplaced = !!current && (current.replaced || []).some(r => r.ts === m.thread_ts) && Number(m.ts) > Number(current.ts);
  if (parent && (!current || (current.ts !== m.thread_ts && !onReplaced))) continue; // never approve a replaced preview
  selected.add(sku);
  const verb = match[1].toLowerCase();
  out.push({json:{ts:m.ts,user:m.user,sku,note:(match[3]||'').trim(),text,
    verdict:verb.startsWith('approv')?'approve':verb.startsWith('revis')?'revise':'reject'}});
}
return out;

// join each verdict with its sheet row; only a row in "Design For Review" takes a verdict
const rows = $('Read Codex Test Rows').first().json.values || [];
const hdr = rows[0] || [];
const iSku = hdr.indexOf('SKU'), iSt = hdr.indexOf('STATUS'), iH = hdr.indexOf('Approval/Revision Notes');
const col = i => String.fromCharCode(65 + i);
const out = [];
for (const it of $('Parse verdicts').all()) {
  const v = it.json; const r = rows.findIndex((row, k) => k > 0 && (row[iSku] || '').trim() === v.sku);
  if (r < 0) { out.push({ json: { ...v, do_write: false, text_out: `${v.sku} is not on the R Designs - Codex Test sheet` } }); continue; }
  const status = (rows[r][iSt] || '').trim();
  if (status !== 'Design For Review') { out.push({ json: { ...v, do_write: false, text_out: `${v.sku} is not waiting for a verdict (status: ${status || 'blank'})` } }); continue; }
  const rowNum = r + 1; const newStatus = v.verdict === 'approve' ? 'Ready for Mock-up' : 'Revise';
  const batch = { valueInputOption: 'RAW', data: [
    { range: `'R Designs - Codex Test'!${col(iSt)}${rowNum}`, values: [[newStatus]] },
    { range: `'R Designs - Codex Test'!${col(iH)}${rowNum}`, values: [[`David via Slack ${new Date().toISOString().slice(0,16)}: ${v.text}`]] } ] };
  out.push({ json: { ...v, do_write: true, batch, text_out: `recorded ${v.verdict} for ${v.sku} → status ${newStatus}; the watcher acts on it within 2 minutes` } });
}
return out;

// Retain the current review parent for every SKU waiting on David, even after it leaves recent history — and the posts it
// replaced that show the SAME Drive preview (R404/R408, 2026-09-15: a corrected pilot was posted again with the same link,
// David replied on the earlier post, and that reply was never read). Only replies after the newest post are read there.
const st = $getWorkflowStaticData('global'); st.review_threads = st.review_threads || {};
const ch = $('Pick channel').first().json;
const rows = $('Read Codex Test Rows').first().json.values || [];
const hdr = rows[0] || [], skuCol = hdr.indexOf('SKU'), statusCol = hdr.indexOf('STATUS');
if (skuCol < 0 || statusCol < 0) throw new Error('R Designs review columns are unavailable');
const waiting = new Set(rows.slice(1).filter(r => r[statusCol] === 'Design For Review').map(r => String(r[skuCol]).trim()));
const history = $('Channel history').first().json;
if (history.ok === false) throw new Error('Slack channel history unavailable');
const messages = history.messages || [];
const preview = t => (String(t || '').match(/drive\.google\.com\/file\/d\/([\w-]+)/) || [])[1] || '';
for (const m of messages) {
  if (m.thread_ts && m.thread_ts !== m.ts) continue;
  const match = String(m.text || '').match(/\b(R\d{2,4})\s+pilot (?:is ready|:)/i);
  if (!match || !waiting.has(match[1].toUpperCase())) continue;
  const sku = match[1].toUpperCase(), prior = st.review_threads[sku], post = {ts:m.ts, text:m.text};
  if (!prior) { st.review_threads[sku] = {...post, replaced:[]}; continue; }
  const replaced = prior.replaced || [];
  if (m.ts === prior.ts || replaced.some(r => r.ts === m.ts)) continue;
  if (Number(m.ts) > Number(prior.ts)) st.review_threads[sku] = {...post, replaced:[{ts:prior.ts, text:prior.text}, ...replaced]};
  else prior.replaced = [...replaced, post];
}
for (const sku of Object.keys(st.review_threads)) {
  if (!waiting.has(sku)) { delete st.review_threads[sku]; continue; }
  const cur = st.review_threads[sku], link = preview(cur.text);
  cur.replaced = (cur.replaced || []).filter(r => link && preview(r.text) === link)
    .sort((a, b) => Number(b.ts) - Number(a.ts)).slice(0, 5);
}
const out = [];
for (const m of Object.values(st.review_threads)) {
  out.push({json:{channel:ch.channel, ts:m.ts, oldest:'0'}});
  for (const r of m.replaced) out.push({json:{channel:ch.channel, ts:r.ts, oldest:m.ts}});
}
// Keep explicit top-level approve R### usable when no review thread is waiting.
if (!out.length && messages.length) out.push({json:{channel:ch.channel, ts:messages[0].thread_ts || messages[0].ts, oldest:ch.oldest}});
return out;

const v = $('Decide').item.json;
const st = $getWorkflowStaticData('global'); st.seen = st.seen || [];
if (!st.seen.includes(v.ts)) st.seen.push(v.ts);
st.seen = st.seen.slice(-1000);
return {json:$json};
